{
  "additionalProperties": false,
  "$schema": "http://json-schema.org/schema#",
  "type": "object",
  "properties": {
    "packageNames": {
      "type": "string",
      "description": "A JSON array containing known package names for the software."
    },
    "name": {
      "$ref": "type.schema.json#/properties/name"
    },
    "checksum": {
      "$ref": "type.schema.json#/properties/checksum"
    },
    "files": {
      "type": "string",
      "description": "A JSON object containing known logFiles/dataFiles/binaryFiles/libraryFiles/configurationFiles arrays for the software."
    },
    "directories": {
      "type": "string",
      "description": "A JSON object containing known logDirectories/dataDirectories/binaryDirectories/libraryDirectories/configurationDirectories arrays for the software."
    },
    "serviceNames": {
      "type": "string",
      "description": "A JSON array containing known service names for the software."
    },
    "commands": {
      "type": "string",
      "description": "A JSON object containing commands and their regular expression format matching rules"
    },
    "desc": {
      "$ref": "type.schema.json#/properties/desc"
    }
  },
  "required": [
    "name",
    "desc",
    "serviceNames",
    "packageNames",
    "files",
    "directories",
    "commands"
  ]
}
